<?php use App\Core\CSRF;?>
<div class="section-heading"><div><div class="eyebrow">Assinatura</div><h1>Isenção de <?=htmlspecialchars($tenant['name'])?></h1><p><?=htmlspecialchars($tenant['plan_name']??'Sem plano')?> · <?=htmlspecialchars($tenant['subscription_status']??'Sem assinatura')?></p></div><a class="btn btn-light" href="/master/tenants/<?=(int)$tenant['id']?>">Voltar</a></div>
<?php if($exemption):?><div class="card border-success mb-4"><div class="card-body"><span class="badge text-bg-success">ISENÇÃO ATIVA</span><h2 class="h4 mt-3"><?=$exemption['exemption_type']==='permanent'?'Permanente':'Temporária'?></h2><p><?=htmlspecialchars($exemption['reason'])?></p><p class="text-secondary">Início: <?=date('d/m/Y H:i',strtotime($exemption['starts_at']))?> · Fim: <?=$exemption['ends_at']?date('d/m/Y H:i',strtotime($exemption['ends_at'])):'sem vencimento'?></p><form method="post" action="/master/tenants/<?=(int)$tenant['id']?>/isencao/revogar" onsubmit="return confirm('Revogar esta isenção?')"><?=CSRF::field()?><button class="btn btn-outline-danger">Revogar isenção</button></form></div></div><?php else:?><form class="card mb-4" method="post" action="/master/tenants/<?=(int)$tenant['id']?>/isencao"><div class="card-body"><?=CSRF::field()?><h2 class="h5">Conceder isenção</h2><div class="row g-3"><div class="col-md-4"><label class="form-label">Tipo</label><select class="form-select" name="exemption_type" data-exemption-type><option value="temporary">Temporária</option><option value="permanent">Permanente</option></select></div><div class="col-md-4"><label class="form-label">Válida até</label><input class="form-control" type="date" name="ends_at" min="<?=date('Y-m-d',strtotime('+1 day'))?>" required data-exemption-end></div><div class="col-md-4"><label class="form-label">Motivo obrigatório</label><input class="form-control" name="reason" minlength="5" required placeholder="Cortesia, parceria, conta interna..."></div></div><button class="btn btn-success mt-3">Autorizar isenção</button><p class="small text-secondary mt-2 mb-0">O plano e seus módulos continuam ativos. Cobranças pendentes futuras são canceladas.</p></div></form><script>(function(){var t=document.querySelector('[data-exemption-type]'),e=document.querySelector('[data-exemption-end]');function sync(){var p=t.value==='permanent';e.disabled=p;e.required=!p;if(p)e.value='';}t.addEventListener('change',sync);sync();})();</script><?php endif;?>
<div class="card"><div class="card-header"><strong>Histórico de isenções</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Concedida em</th><th>Tipo</th><th>Vigência</th><th>Motivo</th><th>Status</th><th>Responsável</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=date('d/m/Y H:i',strtotime($h['created_at']))?></td><td><?=$h['exemption_type']==='permanent'?'Permanente':'Temporária'?></td><td><?=$h['ends_at']?date('d/m/Y',strtotime($h['ends_at'])):'Sem vencimento'?></td><td><?=htmlspecialchars($h['reason'])?></td><td><?=htmlspecialchars(['active'=>'Ativa','revoked'=>'Revogada','expired'=>'Expirada'][$h['status']]??$h['status'])?></td><td><?=htmlspecialchars($h['granted_by_name']??'Sistema')?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="6">Nenhuma isenção registrada.</td></tr><?php endif;?></tbody></table></div></div>
